INSERT INTO `tbl_sinau_materials` (`id`,`tenant_id`,`class_subject_id`,`subject_id`,`major_id`,`grade_level`,`title`,`description`,`type`,`content_url`,`content_text`,`file_id`,`is_published`,`published_at`,`is_public`,`view_count`,`created_by`,`created_at`,`updated_at`) VALUES
('1d0250f1-42ea-45de-a706-f496db86f9b8','738f8d7d-e612-4a49-8658-fe9ce441fcfd','cd2ea415-c19d-49a6-84f9-55ca70552191',NULL,NULL,NULL,'Bilangan Berpangkat dan Logaritma','Ringkasan konsep + contoh soal.','TEXT',NULL,'# Bilangan Berpangkat\n\n$a^m \\times a^n = a^{m+n}$\n\n## Logaritma\n\n$\\log_a b = c \\iff a^c = b$',NULL,1,'2026-09-21 15:10:35',0,0,'c8cd8ca4-1b8e-4834-86b5-0c9b51ff1ec0','2026-09-21 22:10:35','2026-09-21 22:10:35'),
('34fbe0e7-a065-4bbd-89f2-0f1c49a98a46','738f8d7d-e612-4a49-8658-fe9ce441fcfd','dae8660c-5998-4468-8b59-cece46cf05db',NULL,NULL,NULL,'Pengenalan Model OSI 7 Layer','Materi pertemuan 1: fungsi tiap lapisan OSI dan contoh protokolnya.','TEXT',NULL,'# Model OSI\n\nModel OSI membagi komunikasi jaringan menjadi 7 lapisan:\n\n1. **Physical** – kabel, sinyal listrik\n2. **Data Link** – MAC address, switch\n3. **Network** – IP address, router\n4. **Transport** – TCP/UDP, port\n5. **Session** – pengelolaan sesi\n6. **Presentation** – enkripsi, format data\n7. **Application** – HTTP, FTP, DNS\n\n> Cara mengingat: *Please Do Not Throw Sausage Pizza Away*.',NULL,1,'2026-09-21 15:10:35',0,0,'583ab4c1-5a1d-4998-abcf-1b992b770ddc','2026-09-21 22:10:35','2026-09-21 22:10:35'),
('3e11d313-5348-4cc5-9faf-5bc7551bdade','738f8d7d-e612-4a49-8658-fe9ce441fcfd','dae8660c-5998-4468-8b59-cece46cf05db',NULL,NULL,NULL,'Video: Subnetting IPv4 dalam 15 menit','Tonton lalu kerjakan latihan di kuis.','VIDEO','https://www.youtube.com/watch?v=dQw4w9WgXcQ',NULL,NULL,1,'2026-09-21 15:10:35',0,0,'583ab4c1-5a1d-4998-abcf-1b992b770ddc','2026-09-21 22:10:35','2026-09-21 22:10:35'),
('a96065fc-a9e7-4a19-968b-ea2359b9f11e','738f8d7d-e612-4a49-8658-fe9ce441fcfd',NULL,'2050810d-776d-49fa-8c59-3ab13b3d67ac',NULL,10,'Etika Digital dan Keamanan Akun','Materi umum untuk semua kelas X.','TEXT',NULL,'# Etika Digital\n\nGunakan kata sandi kuat, aktifkan verifikasi dua langkah, dan jangan bagikan data pribadi.',NULL,1,'2026-09-21 15:10:35',1,0,'583ab4c1-5a1d-4998-abcf-1b992b770ddc','2026-09-21 22:10:35','2026-09-21 22:10:35');
